    howto_wok_title:"The WoK",
    howto_kit_title:"Kanji Kitchen",
    howto_wok_1:"<b>Start here:</b> pick a block of 100 on the strip (or press <b>Jump to where I left off</b>), then press one of the drill buttons <b>under the wall</b> — they send that block to the Kanji Kitchen. Every answer there comes back here as a stamp.",
    howto_wok_2:"<b>Reading the wall:</b> <span class=\"howto-sw is-new\"></span> blank = not practised yet · <span class=\"howto-sw is-shaky\"></span> red outline = shaky, you missed it · <span class=\"howto-sw is-solid\"></span> coloured = solid, you know it. The filters <b>All · Shaky · Not started · Solid</b> show just those.",
    howto_wok_3:"<b>Tap any stamp</b> to open its card: the keyword (what it means), the on and kun readings, example words, and how often you got it right and wrong. The speaker button reads out <b>every</b> reading of the kanji, and each example word has its own.",
    howto_wok_4:"<b>The drill buttons under the wall</b> send kanji to the Kitchen: the block’s shaky ones, the ones you haven’t started, the whole block, or every shaky kanji on the wall. <b>Enter the Kitchen</b> (next to the tabs) just walks in and starts at 1–100. A good habit: new ones first, then clear the shaky ones.",
    howto_wok_5:"<b>One at a time</b> shows the block as flashcards — a good first look before you drill it.",
    howto_wok_6:"<b>Search</b> finds a kanji by the character, its keyword or its KLC number: 日, “sun” or #330.",
    howto_wok_7:"<b>How stamps change:</b> right once in the Kitchen = solid · a miss = shaky · two right in a row = solid again. <b>Show me the answer</b> changes nothing. <b>Colours</b> only changes the look (Mosaic, Ink or Spectrum).",
    howto_wok_8:"Your progress is saved in this browser — no account needed, and nothing leaves your device.",
    howto_kit_1:"<b>Start here:</b> just begin. Type what the kanji means and press <b>Enter</b>. Don’t know it? Press <b>Show me the answer</b> — you see the meaning, the readings and an example word, and it costs you nothing: no miss, your streak stays, the wall doesn’t change. Each time the answer card opens, the kanji’s main reading is said out loud, so you learn how it sounds too. Press <b>Enter</b> for the next one and keep going.",
    howto_kit_2:"<b>Right or wrong?</b> The card lights up with a green outline when you’re right and a red one when you’re not. A near-miss spelling gets one more try; plurals and the bracketed bits of a keyword don’t matter. Reviewing a block you know? The <b>⚙ gear</b> at the end of the score bar can skip straight to the next kanji after a right answer. Want it quiet? The same gear can switch the spoken reading off.",
    howto_kit_3:"<b>What you’re drilling:</b> you start on the first block, <b>1–100</b>. When those feel solid, pick the next block from the menu on the right — or a bigger range, everything, or <b>only the ones you’ve got wrong</b>. Sent here from the wall? Then you drill that block, or just your shaky ones, in <b>rounds of ten</b> — the pips in the score bar show how far you are.",
    howto_kit_4:"<b>Direction:</b> <i>Kanji → Keyword</i> shows the kanji and you give its meaning. <i>Keyword → Kanji</i> shows the meaning and you give the kanji.",
    howto_kit_5:"<b>Type it or Pick it:</b> typing is harder but sticks better; <b>Pick it</b> gives four choices to tap. New to a block? Start with Pick it, then switch to Type it once the kanji feel familiar.",
    howto_kit_6:"<b>Hear the reading</b> (top left of the card) says the kanji’s main reading — the one you’d hear when it stands on its own, like 山 やま or 食 たべる. After you answer, the speaker buttons say that reading and the example word. The wall reads out every reading.",
    howto_kit_7:"<b>The score bar</b> — Right, Wrong, Streak, Best, Skipped — is just for this visit; <b>Reset Score</b> clears it and nothing else. Kanji you miss collect under the card so you can look at them again.",
    howto_kit_8:"<b>It all goes on the wall:</b> a right answer makes a new kanji solid on The WoK; a miss turns it shaky (red outline); two right in a row win it back.",
    howto_kit_9:"<b>Back to the wall:</b> the <b>← 壁 Wall</b> button at the left of the toolbar, any time. At the end of a round you also get buttons to go back or drill what’s still shaky. Stuck on one? Open <b>Katsu</b> (bottom right) and ask him.",
    kd_hear:"Hear the reading",
