    howto_label:"So funktioniert’s",
    howto_hide:"einrollen",
    howto_show:"So funktioniert’s",
    howto_toggle:"Einrollen / ausrollen",
    howto_wok_title:"The WoK",
    howto_kit_title:"Kanji Kitchen",
    howto_wok_1:"<b>So fängst du an:</b> Wähle in der Leiste einen Block mit 100 Kanji (oder <b>Dort weitermachen, wo ich war</b>) und drück einen der Übungsknöpfe <b>unter der Wand</b> — sie schicken den Block in die Kanji Kitchen. Jede Antwort dort landet hier als Stempel.",
    howto_wok_2:"<b>So liest du die Wand:</b> <span class=\"howto-sw is-new\"></span> leer = noch nicht geübt · <span class=\"howto-sw is-shaky\"></span> roter Rand = wackelig, du lagst falsch · <span class=\"howto-sw is-solid\"></span> farbig = sitzt. Die Filter <b>Alle · Wackelig · Noch nicht begonnen · Sitzt</b> zeigen nur diese.",
    howto_wok_3:"<b>Tippe auf einen Stempel</b>, um seine Karte zu öffnen: das Schlüsselwort (die Bedeutung), On- und Kun-Lesungen, Beispielwörter und wie oft du richtig und falsch lagst. Der Lautsprecher-Knopf liest <b>alle</b> Lesungen des Kanji vor, und jedes Beispielwort hat seinen eigenen.",
    howto_wok_4:"<b>Die Übungsknöpfe unter der Wand</b> schicken Kanji in die Küche: die wackeligen des Blocks, die noch nicht begonnenen, den ganzen Block oder alle wackeligen der Wand. <b>Ab in die Küche</b> (neben den Reitern) geht einfach hinein und startet bei 1–100. Eine gute Gewohnheit: erst die neuen, dann die wackeligen abarbeiten.",
    howto_wok_5:"<b>Einzeln</b> zeigt den Block als Karteikarten — ein guter erster Blick, bevor du ihn übst.",
    howto_wok_6:"<b>Suche</b> findet ein Kanji über das Zeichen, sein Schlüsselwort oder seine KLC-Nummer: 日, „sun“ oder #330.",
    howto_wok_7:"<b>Wie sich Stempel ändern:</b> einmal richtig in der Kitchen = sitzt · falsch = wackelig · zweimal hintereinander richtig = sitzt wieder. <b>Antwort zeigen</b> ändert nichts. <b>Farben</b> ändert nur das Aussehen (Mosaik, Tinte oder Spektrum).",
    howto_wok_8:"Dein Fortschritt wird in diesem Browser gespeichert — kein Konto nötig, nichts verlässt dein Gerät.",
    howto_kit_1:"<b>So fängst du an:</b> Leg einfach los. Tippe ein, was das Kanji bedeutet, und drück <b>Enter</b>. Du weißt es nicht? Drück <b>Antwort zeigen</b> — du siehst Bedeutung, Lesungen und ein Beispielwort, und es kostet dich nichts: kein Fehler, deine Serie bleibt, die Wand ändert sich nicht. Jedes Mal, wenn die Antwortkarte aufgeht, wird die Hauptlesung laut vorgesprochen, damit du auch lernst, wie das Kanji klingt. Mit <b>Enter</b> geht’s zum nächsten, und weiter so.",
    howto_kit_2:"<b>Richtig oder falsch?</b> Die Karte leuchtet grün auf, wenn du richtig liegst, und rot, wenn nicht. Bei einem knappen Tippfehler bekommst du noch einen Versuch; Plural und Klammerteile im Schlüsselwort sind egal. Wiederholst du einen Block, den du kennst? Das <b>⚙ Zahnrad</b> am Ende der Punkteleiste kann nach einer richtigen Antwort direkt zum nächsten Kanji springen. Lieber leise? Über dasselbe Zahnrad lässt sich das Vorsprechen ausschalten.",
    howto_kit_3:"<b>Was du übst:</b> Du startest mit dem ersten Block, <b>1–100</b>. Sitzen die, wähle im Menü rechts den nächsten Block — oder einen größeren Bereich, alles oder <b>nur die, die ich falsch hatte</b>. Kommst du von der Wand? Dann übst du diesen Block oder nur deine wackeligen in <b>Zehnerrunden</b> — die Punkte in der Punkteleiste zeigen, wie weit du bist.",
    howto_kit_4:"<b>Richtung:</b> <i>Kanji → Schlüsselwort</i> zeigt das Kanji, du gibst die Bedeutung an. <i>Schlüsselwort → Kanji</i> zeigt die Bedeutung, du gibst das Kanji an.",
    howto_kit_5:"<b>Eintippen oder Auswählen:</b> Tippen ist schwerer, bleibt aber besser hängen; <b>Auswählen</b> bietet vier Möglichkeiten zum Antippen. Neu in einem Block? Fang mit Auswählen an und wechsle zu Eintippen, sobald dir die Kanji vertraut sind.",
    howto_kit_6:"<b>Lesung anhören</b> (oben links auf der Karte) spricht die Hauptlesung des Kanji — die, die man hört, wenn es allein steht, etwa 山 やま oder 食 たべる. Nach der Antwort sprechen die Lautsprecher-Knöpfe diese Lesung und das Beispielwort. Auf der Wand werden alle Lesungen vorgelesen.",
    howto_kit_7:"<b>Die Punkteleiste</b> — Richtig, Falsch, Serie, Rekord, Übersprungen — gilt nur für diesen Besuch; <b>Punkte zurücksetzen</b> löscht sie und sonst nichts. Kanji, die du verfehlst, sammeln sich unter der Karte, damit du sie dir noch einmal ansehen kannst.",
    howto_kit_8:"<b>Alles landet an der Wand:</b> Eine richtige Antwort lässt ein neues Kanji in The WoK sitzen; ein Fehler macht es wackelig (roter Rand); zweimal hintereinander richtig holt es zurück.",
    howto_kit_9:"<b>Zurück zur Wand:</b> der Knopf <b>← 壁 Wand</b> links in der Leiste, jederzeit. Am Ende einer Runde gibt es außerdem Knöpfe zum Zurückgehen oder zum Üben dessen, was noch wackelig ist. Hängst du fest? Öffne <b>Katsu</b> (unten rechts) und frag ihn.",
    kd_hear:"Lesung anhören",
    kd_r_start:"hier anfangen",
    kd_set_btn:"Einstellungen",
    kd_set_title:"Küchen-Einstellungen",
