    kd_set_show:"Antwortkarte zeigen",
    kd_set_show_d:"Bedeutung, Lesungen und ein Beispielwort sehen, dann Enter drücken. Am besten, solange ein Block neu ist.",
    kd_set_fast:"Direkt zum nächsten Kanji",
    kd_set_fast_d:"Kurz grün aufleuchten, dann das nächste. Zum Wiederholen von Kanji, die du schon kannst.",
    kd_set_note:"Bei einer falschen Antwort wird immer angehalten, damit du die richtige siehst.",
