    kw_cm_mosaic_h:"Chaque kanji garde une couleur fixe pour toujours. Joli ; la couleur ne veut rien dire.",
    kw_cm_ink_h:"Votre couleur, qui s’imprègne : une teinte claire après la première bonne réponse, la couleur pleine à deux d’affilée, l’encre profonde à cinq.",
