    howto_label:"Comment ça marche",
    howto_hide:"enrouler",
    howto_show:"Comment ça marche",
    howto_toggle:"Enrouler / dérouler",
    howto_wok_title:"The WoK",
    howto_kit_title:"Kanji Kitchen",
    howto_wok_1:"<b>Pour commencer :</b> choisis un bloc de 100 dans la bande (ou <b>Reprendre où j'en étais</b>), puis appuie sur un des boutons d’exercice <b>sous le mur</b> — ils envoient ce bloc à la Kanji Kitchen. Chaque réponse là-bas revient ici sous forme de tampon.",
    howto_wok_2:"<b>Lire le mur :</b> <span class=\"howto-sw is-new\"></span> vide = pas encore travaillé · <span class=\"howto-sw is-shaky\"></span> contour rouge = fragile, tu t’es trompé · <span class=\"howto-sw is-solid\"></span> en couleur = acquis. Les filtres <b>Tous · Fragiles · Pas commencés · Acquis</b> n’affichent que ceux-là.",
    howto_wok_3:"<b>Touche un tampon</b> pour ouvrir sa carte : le mot-clé (le sens), les lectures on et kun, des mots d’exemple et combien de fois tu as eu juste ou faux. Le bouton haut-parleur lit <b>toutes</b> les lectures du kanji, et chaque mot d’exemple a le sien.",
    howto_wok_4:"<b>Les boutons sous le mur</b> envoient des kanji à la cuisine : les fragiles du bloc, ceux pas commencés, tout le bloc, ou tous les fragiles du mur. <b>Entrer en cuisine</b> (à côté des onglets) y entre simplement et commence à 1–100. Une bonne habitude : d’abord les nouveaux, puis les fragiles.",
    howto_wok_5:"<b>Un par un</b> montre le bloc en cartes — un bon premier regard avant de t’exercer.",
    howto_wok_6:"<b>La recherche</b> trouve un kanji par le caractère, son mot-clé ou son numéro KLC : 日, « sun » ou #330.",
    howto_wok_7:"<b>Comment les tampons changent :</b> juste une fois dans la Kitchen = acquis · une erreur = fragile · deux justes d’affilée = acquis à nouveau. <b>Voir la réponse</b> ne change rien. <b>Couleurs</b> ne change que l’apparence (Mosaïque, Encre ou Spectre).",
    howto_wok_8:"Ta progression est enregistrée dans ce navigateur — pas de compte, et rien ne quitte ton appareil.",
    howto_kit_1:"<b>Pour commencer :</b> lance-toi. Tape ce que le kanji veut dire et appuie sur <b>Entrée</b>. Tu ne sais pas ? Appuie sur <b>Voir la réponse</b> — tu vois le sens, les lectures et un mot d’exemple, et ça ne te coûte rien : pas d’erreur, ta série reste, le mur ne change pas. À chaque carte réponse, la lecture principale est dite à voix haute, pour que tu apprennes aussi comment il se prononce. <b>Entrée</b> pour le suivant, et continue.",
    howto_kit_2:"<b>Juste ou faux ?</b> La carte s’entoure de vert quand tu as juste et de rouge sinon. Une faute de frappe de peu te donne un second essai ; le pluriel et les parties entre crochets du mot-clé ne comptent pas. Tu révises un bloc que tu connais ? La <b>⚙ roue</b> au bout de la barre de score peut passer directement au kanji suivant après une bonne réponse. Tu préfères le silence ? La même roue coupe la lecture à voix haute.",
    howto_kit_3:"<b>Ce que tu travailles :</b> tu commences par le premier bloc, <b>1–100</b>. Quand ils sont acquis, choisis le bloc suivant dans le menu à droite — ou une plage plus large, tout, ou <b>seulement ceux que j’ai ratés</b>. Venu du mur ? Alors tu travailles ce bloc, ou seulement tes fragiles, par <b>manches de dix</b> — les points de la barre de score montrent où tu en es.",
    howto_kit_4:"<b>Sens :</b> <i>Kanji → mot-clé</i> montre le kanji, tu donnes son sens. <i>Mot-clé → kanji</i> montre le sens, tu donnes le kanji.",
    howto_kit_5:"<b>Je l’écris ou Je choisis :</b> écrire est plus dur mais retient mieux ; <b>Je choisis</b> propose quatre réponses à toucher. Nouveau bloc ? Commence par Je choisis, puis passe à Je l’écris quand les kanji te sont familiers.",
    howto_kit_6:"<b>Écouter la lecture</b> (en haut à gauche de la carte) dit la lecture principale du kanji — celle qu’on entend quand il est seul, comme 山 やま ou 食 たべる. Après ta réponse, les boutons haut-parleur disent cette lecture et le mot d’exemple. Le mur, lui, lit toutes les lectures.",
    howto_kit_7:"<b>La barre de score</b> — Justes, Fausses, Série, Record, Passées — ne vaut que pour cette visite ; <b>Réinitialiser le score</b> l’efface et rien d’autre. Les kanji manqués s’accumulent sous la carte pour que tu puisses les revoir.",
    howto_kit_8:"<b>Tout va sur le mur :</b> une bonne réponse rend un nouveau kanji acquis sur The WoK ; une erreur le rend fragile (contour rouge) ; deux justes d’affilée le récupèrent.",
    howto_kit_9:"<b>Retour au mur :</b> le bouton <b>← 壁 Mur</b> à gauche de la barre, à tout moment. En fin de manche, tu as aussi des boutons pour revenir ou retravailler ce qui reste fragile. Bloqué ? Ouvre <b>Katsu</b> (en bas à droite) et demande-lui.",
    kd_hear:"Écouter la lecture",
    kd_r_start:"commence ici",
    kd_set_btn:"Réglages",
