    kw_cm_mosaic_h:"每个汉字永远保持一种固定颜色。好看，但颜色没有含义。",
    kw_cm_ink_h:"你选的颜色逐渐加深：第一次答对是浅色，连续两次是全色，连续五次是深墨。",
