    howto_label:"使用说明",
    howto_hide:"收起",
    howto_show:"使用说明",
    howto_toggle:"收起 / 展开",
    howto_wok_title:"The WoK",
    howto_kit_title:"Kanji Kitchen",
    howto_wok_1:"<b>从这里开始：</b>在横条上选一组 100 个字（或点<b>跳到上次的位置</b>），然后点<b>字墙下方</b>的练习按钮——它们会把这一组送进 Kanji Kitchen。那里的每个回答都会以印章的形式回到这里。",
    howto_wok_2:"<b>怎么看字墙：</b><span class=\"howto-sw is-new\"></span> 空白 = 还没练过 · <span class=\"howto-sw is-shaky\"></span> 红框 = 不牢，你答错过 · <span class=\"howto-sw is-solid\"></span> 有颜色 = 已掌握。筛选<b>全部 · 不牢 · 未开始 · 已掌握</b>只显示对应的字。",
    howto_wok_3:"<b>点任意一枚印章</b>打开字卡：关键词（字义）、音读和训读、例词，以及你答对和答错的次数。喇叭按钮会读出这个字的<b>所有</b>读音，每个例词也有自己的喇叭。",
    howto_wok_4:"<b>字墙下方的练习按钮</b>把字送进厨房：本组不牢的字、还没开始的字、整组，或整面墙上所有不牢的字。<b>进厨房</b>（在标签旁边）直接进去，从 1–100 开始。好习惯：先练新字，再清掉不牢的。",
    howto_wok_5:"<b>逐个学</b>把这一组做成闪卡——练习之前先看一遍很合适。",
    howto_wok_6:"<b>搜索</b>可以按汉字本身、关键词或 KLC 编号查找：日、“sun”或 #330。",
    howto_wok_7:"<b>印章怎么变：</b>在 Kitchen 答对一次 = 已掌握 · 答错 = 不牢 · 连续答对两次 = 重新掌握。<b>显示答案</b>什么都不改变。<b>颜色</b>只改变外观（马赛克、墨色或光谱）。",
    howto_wok_8:"你的进度保存在这个浏览器里——不用注册，数据不会离开你的设备。",
    howto_kit_1:"<b>从这里开始：</b>直接开始就好。输入这个汉字的意思，按 <b>Enter</b>。不知道？点<b>显示答案</b>——你会看到字义、读音和一个例词，而且没有任何代价：不算答错，连对不断，字墙也不变。每次答案卡打开时都会朗读这个字的主要读音，让你也记住它怎么念。再按 <b>Enter</b> 进入下一个，继续练。",
    howto_kit_2:"<b>对还是错？</b>答对时字卡亮起绿色边框，答错时是红色。拼写只差一点会再给你一次机会；关键词的复数和括号里的部分都不影响。复习已经会的一组？得分栏末尾的<b>⚙ 齿轮</b>可以设置答对后直接进入下一个字。想安静一点？同一个齿轮里可以关掉朗读。",
    howto_kit_3:"<b>练的是什么：</b>默认从第一组 <b>1–100</b> 开始。练熟之后，在右边的菜单里选下一组——或者更大的范围、全部，或<b>只练答错过的</b>。从字墙过来的？那就是练那一组，或只练你不牢的字，每<b>十个一轮</b>——得分栏里的小点显示进度。",
    howto_kit_4:"<b>方向：</b><i>汉字 → 关键词</i>显示汉字，你答出意思。<i>关键词 → 汉字</i>显示意思，你答出汉字。",
    howto_kit_5:"<b>输入还是选择：</b>输入更难，但记得更牢；<b>选择</b>给出四个选项点选。刚开始一组？先用选择，等字熟了再换成输入。",
    howto_kit_6:"<b>听读音</b>（字卡左上角）读出这个字的主要读音——也就是它单独使用时的读法，比如 山 やま、食 たべる。回答之后，喇叭按钮会读出这个读音和例词。字墙上则会读出所有读音。",
    howto_kit_7:"<b>得分栏</b>——答对、答错、连对、最高、跳过——只算这次访问；<b>重置得分</b>只清除这些。答错的字会收集在字卡下面，方便你再看一遍。",
    howto_kit_8:"<b>一切都记在字墙上：</b>答对一次，新字在 The WoK 上变为已掌握；答错变为不牢（红框）；连续答对两次就能找回来。",
    howto_kit_9:"<b>返回字墙：</b>工具栏左边的 <b>← 壁 字墙</b> 按钮，随时可用。一轮结束时还有按钮可以返回或再练仍不牢的字。卡住了？打开 <b>Katsu</b>（右下角）问他。",
