    creator_note:"<strong>来自作者的话：</strong><br>我做 Katsuyō Academy，是因为我自己需要它。零散的课本章节、让人摸不着头脑的网上资料、总是差一点合用的记忆卡应用——我希望把这些都放在一处，按照最适合我自己的方式来设计。这里就是那个地方。如果它也能帮到你，那它就没白做。<span class=\"jp\">頑張ってください！</span>",
