    howto_toggle:"巻く / 開く",
    howto_wok_title:"The WoK",
    howto_kit_title:"Kanji Kitchen",
    howto_wok_1:"<b>はじめかた：</b>帯から100字のブロックを選び（または<b>続きから始める</b>）、<b>壁の下</b>にある練習ボタンを押します——そのブロックが Kanji Kitchen に送られます。そこでの答えはすべてここにハンコとして戻ってきます。",
    howto_wok_2:"<b>壁の見かた：</b><span class=\"howto-sw is-new\"></span> 空白＝まだ練習していない · <span class=\"howto-sw is-shaky\"></span> 赤い枠＝あやふや（間違えた字）· <span class=\"howto-sw is-solid\"></span> 色つき＝定着。フィルター<b>すべて・あやふや・未着手・定着</b>で絞り込めます。",
    howto_wok_3:"<b>ハンコをタップ</b>するとカードが開きます：キーワード（意味）、音読み・訓読み、例語、正解・不正解の回数。スピーカーボタンはその字の読みを<b>すべて</b>読み上げ、例語にもそれぞれボタンがあります。",
    howto_wok_4:"<b>壁の下の練習ボタン</b>で字をキッチンに送ります：ブロックのあやふやな字、まだ手をつけていない字、ブロック全部、壁のあやふやな字すべて。<b>キッチンへ</b>（タブの横）はそのまま入って 1–100 から始めます。おすすめは、新しい字から始めて、あやふやな字を片づけること。",
    howto_wok_5:"<b>一枚ずつ</b>はブロックをフラッシュカードで見せます——練習の前にざっと見るのにぴったり。",
    howto_wok_6:"<b>検索</b>は字そのもの、キーワード、KLC 番号で探せます：日、sun、#330 など。",
    howto_wok_7:"<b>ハンコの変わりかた：</b>Kitchen で1回正解＝定着 · 間違い＝あやふや · 2回続けて正解＝また定着。<b>答えを見る</b>では何も変わりません。<b>色</b>は見た目だけを変えます（モザイク・墨・スペクトル）。",
    howto_wok_8:"進み具合はこのブラウザに保存されます——登録不要で、データが端末の外に出ることはありません。",
    howto_kit_1:"<b>はじめかた：</b>とにかく始めてみましょう。漢字の意味を入力して <b>Enter</b>。わからなければ<b>答えを見る</b>——意味・読み・例語が表示され、何のマイナスもありません：不正解にならず、連続正解も途切れず、壁も変わりません。答えのカードが開くたびに代表的な読みが読み上げられるので、音も一緒に覚えられます。<b>Enter</b> で次へ進み、どんどん続けましょう。",
    howto_kit_2:"<b>正解？不正解？</b>正解ならカードが緑の枠で、不正解なら赤い枠で光ります。つづりが惜しいときはもう一度チャンスがあります。キーワードの複数形やかっこ内の部分は気にしなくて大丈夫です。覚えたブロックの復習なら、スコア欄の端にある<b>⚙ 歯車</b>で、正解したらすぐ次の字へ進むように設定できます。音を消したいときも、同じ歯車から読み上げをオフにできます。",
    howto_kit_3:"<b>練習する範囲：</b>最初は第1ブロック <b>1–100</b> から始まります。覚えたら右のメニューで次のブロックへ——もっと広い範囲、全部、<b>間違えた字だけ</b>も選べます。壁から来た場合は、そのブロック、またはあやふやな字だけを<b>10問ずつのラウンド</b>で練習します——スコア欄の点が進み具合です。",
    howto_kit_4:"<b>方向：</b><i>漢字 → キーワード</i>は漢字を見て意味を答えます。<i>キーワード → 漢字</i>は意味を見て漢字を答えます。",
    howto_kit_5:"<b>入力するか選ぶか：</b>入力は難しいぶん記憶に残ります。<b>選ぶ</b>は4択をタップ。新しいブロックはまず「選ぶ」で始めて、字に慣れたら「入力する」に切り替えましょう。",
    howto_kit_6:"<b>読みを聞く</b>（カード左上）はその字の代表的な読み——単独で使うときの読み、たとえば 山 やま、食 たべる——を読み上げます。答えたあとは、スピーカーボタンでその読みと例語を聞けます。壁ではすべての読みを読み上げます。",
    howto_kit_7:"<b>スコア欄</b>——正解・不正解・連続正解・最高記録・スキップ——は今回の訪問だけのものです。<b>得点をリセット</b>で消えるのはこれだけ。間違えた字はカードの下に集まるので、あとで見直せます。",
    howto_kit_8:"<b>すべて壁に記録：</b>正解すると新しい字は The WoK で定着に、間違えるとあやふや（赤い枠）に、2回続けて正解すると元に戻ります。",
    howto_kit_9:"<b>壁に戻る：</b>ツールバー左端の <b>← 壁 戻る</b> ボタンでいつでも。ラウンドの終わりには、戻るボタンやあやふやな字をもう一度練習するボタンも出ます。困ったら<b>Katsu</b>（右下）に聞いてみましょう。",
