    intro_p1:'活用道場は、<strong>学習者が学習者のために作った個人プロジェクト</strong>です。教科書の代わりになろうとも、次の語学アプリになろうともしていません。かわりに、日本語の土台となる要素 — 何度も引き、何度も練習することになるもの — を扱う、つながりあった一式のツールをそろえています。',
